targets.expr:
max by (base, bluetooth) (
    label_replace(sp_rtk_base_input_info{job="sp-rtk-base", kind!="bluetooth"}, "bluetooth", "n/a · $1", "kind", "(.*)")
  or count_values by (base) ("bluetooth",
       sp_rtk_base_bluetooth_link_strength{job="sp-rtk-base"}
       unless on (base) sp_rtk_base_input_info{job="sp-rtk-base", kind!="bluetooth"})
)

max by (base, kind) (
    sp_rtk_base_input_connected{job="sp-rtk-base", base=~"$base"}
  * on (base) group_left (kind) label_replace(sp_rtk_base_input_info{job="sp-rtk-base", base=~"$base"}, "kind", "$1 Input", "kind", "(.+)")
  or on (base) label_replace(sp_rtk_base_input_connected{job="sp-rtk-base", base=~"$base"}, "kind", "Input", "", "")
)
